// ---------- core algorithm (kept 1:1 with the spec text above) ----------

const enc = new TextEncoder();

async function sha256Hex(str){
  const buf = await crypto.subtle.digest('SHA-256', enc.encode(str));
  const bytes = new Uint8Array(buf);
  let out = '';
  for (let i=0;i<bytes.length;i++) out += bytes[i].toString(16).padStart(2,'0');
  return out;
}

function normalize(text){
  return text.toLowerCase().replace(/\s+/g, ' ').trim();
}

function shingleSet(normText, k){
  if (!normText) return [];
  const words = normText.split(' ');
  if (words.length < k) return [];
  const seen = new Set();
  for (let i=0;i<=words.length-k;i++){
    seen.add(words.slice(i, i+k).join(' '));
  }
  return [...seen];
}

const MOD32 = 1n << 32n;
let permCache = new Map(); // N -> [{a,b}]

async function getPerms(N){
  if (permCache.has(N)) return permCache.get(N);
  const perms = new Array(N);
  for (let i=0;i<N;i++){
    const ah = await sha256Hex('kar-shingle-perm-a-'+i);
    const bh = await sha256Hex('kar-shingle-perm-b-'+i);
    const a = (BigInt('0x'+ah.slice(0,8)) | 1n);
    const b = BigInt('0x'+bh.slice(0,8));
    perms[i] = {a,b};
  }
  permCache.set(N, perms);
  return perms;
}

// returns { shingleCount, normalized, normalizedSha256, sig (BigInt[] or null), signatureSha256 }
async function analyzeDoc(rawText, k, N){
  const norm = normalize(rawText);
  const normalizedSha256 = await sha256Hex(norm);
  const shs = shingleSet(norm, k);
  if (shs.length === 0){
    return { shingleCount: 0, normalized: norm, normalizedSha256, sig: null, signatureSha256: null };
  }
  const baseHashes = new Array(shs.length);
  for (let i=0;i<shs.length;i++){
    const h = await sha256Hex(shs[i]);
    baseHashes[i] = BigInt('0x'+h.slice(0,8));
  }
  const perms = await getPerms(N);
  const sig = new Array(N);
  for (let i=0;i<N;i++){
    const {a,b} = perms[i];
    let min = null;
    for (let j=0;j<baseHashes.length;j++){
      const v = (a * baseHashes[j] + b) % MOD32;
      if (min === null || v < min) min = v;
    }
    sig[i] = min;
  }
  const sigHex = sig.map(v => v.toString(16).padStart(8,'0')).join('');
  const signatureSha256 = await sha256Hex(sigHex);
  return { shingleCount: shs.length, normalized: norm, normalizedSha256, sig, signatureSha256 };
}

function similarityOf(sigA, sigB){
  if (!sigA || !sigB) return null;
  let match = 0;
  for (let i=0;i<sigA.length;i++) if (sigA[i] === sigB[i]) match++;
  return { matches: match, total: sigA.length, ratio: match / sigA.length };
}

function verdictOf(docA, docB, sim){
  if (docA.shingleCount === 0 || docB.shingleCount === 0) return 'INSUFFICIENT-DATA';
  if (docA.normalizedSha256 === docB.normalizedSha256) return 'IDENTICAL';
  const r = sim.ratio;
  if (r >= 0.75) return 'NEAR-DUPLICATE';
  if (r >= 0.35) return 'OVERLAPPING';
  return 'DISTINCT';
}

function canonJSON(obj){
  if (obj === null || typeof obj !== 'object') return JSON.stringify(obj);
  if (Array.isArray(obj)) return '[' + obj.map(canonJSON).join(',') + ']';
  const keys = Object.keys(obj).sort();
  return '{' + keys.map(k => JSON.stringify(k) + ':' + canonJSON(obj[k])).join(',') + '}';
}

async function buildReceipt(k, N, docA, docB, sim, verdict){
  const receipt = {
    algorithm: 'kar-shingle-minhash-v1',
    k, n: N,
    docA: { shingleCount: docA.shingleCount, normalizedSha256: docA.normalizedSha256, signatureSha256: docA.signatureSha256 },
    docB: { shingleCount: docB.shingleCount, normalizedSha256: docB.normalizedSha256, signatureSha256: docB.signatureSha256 },
    similarityMatches: sim ? sim.matches : null,
    similarityTotal: sim ? sim.total : null,
    verdict
  };
  const canon = canonJSON(receipt);
  const hash = await sha256Hex(canon);
  return { receipt, canon, hash };
}

