const SELF = {
  K: 5, N: 64,
  A: "The quarterly steering committee reviewed the migration plan in detail and agreed that the pilot cohort would move to the new billing platform first, with the remaining regions following in staggered waves once the pilot had run cleanly for two full billing cycles without any reconciliation errors or customer complaints.",
  get B(){ return this.A + " A follow-up review is scheduled for the end of the second cycle."; },
  D: "The quarterly steering committee reviewed the migration plan in detail and agreed that the pilot cohort would shift to the new billing platform first, with the remaining regions following in staggered waves once the pilot had run cleanly for two full billing cycles without any reconciliation errors or customer complaints.",
  C: "Sedimentary rock layers exposed along the canyon wall record millions of years of gradual deposition, with each distinct band reflecting a different era of climate, water flow, and mineral content that geologists can read like pages in a very slow, very patient book."
};

// impl: optional stand-ins for analyzeDoc / similarityOf / verdictOf, so the tests can prove each check
// actually fails on a faulty implementation (a self-test that cannot fail proves nothing). The page passes none.
async function runSelfTest(impl){
  impl = impl || { analyzeDoc: analyzeDoc, similarityOf: similarityOf, verdictOf: verdictOf };
  const rows = [];
  let allPass = true;

  function addRow(label, pass, detail){
    rows.push({label, pass, detail});
    if (!pass) allPass = false;
  }

  try {
    const k = SELF.K, N = SELF.N;
    const a1 = await impl.analyzeDoc(SELF.A, k, N);
    const a2 = await impl.analyzeDoc(SELF.A, k, N);
    const b  = await impl.analyzeDoc(SELF.B, k, N);
    const c  = await impl.analyzeDoc(SELF.C, k, N);
    const d  = await impl.analyzeDoc(SELF.D, k, N);

    // 1. identical resubmission -> IDENTICAL, ratio exactly 1
    const simAA = impl.similarityOf(a1.sig, a2.sig);
    const vAA = impl.verdictOf(a1, a2, simAA);
    addRow('Re-submission verifies as IDENTICAL (ratio=1.0)',
      vAA === 'IDENTICAL' && simAA.ratio === 1,
      'verdict=' + vAA + ' ratio=' + simAA.ratio);

    // 2. disguised duplicate (sentence appended) -> caught as NEAR-DUPLICATE, not IDENTICAL
    const simAB = impl.similarityOf(a1.sig, b.sig);
    const vAB = impl.verdictOf(a1, b, simAB);
    addRow('Padded duplicate is caught as NEAR-DUPLICATE (not IDENTICAL)',
      vAB === 'NEAR-DUPLICATE',
      'verdict=' + vAB + ' ratio=' + simAB.ratio.toFixed(3));

    // 3. disguised duplicate (one word swapped) -> caught as NEAR-DUPLICATE
    const simAD = impl.similarityOf(a1.sig, d.sig);
    const vAD = impl.verdictOf(a1, d, simAD);
    addRow('Word-swap duplicate is caught as NEAR-DUPLICATE',
      vAD === 'NEAR-DUPLICATE',
      'verdict=' + vAD + ' ratio=' + simAD.ratio.toFixed(3));

    // 4. unrelated document -> DISTINCT, no false positive
    const simAC = impl.similarityOf(a1.sig, c.sig);
    const vAC = impl.verdictOf(a1, c, simAC);
    addRow('Unrelated document is not falsely flagged (DISTINCT)',
      vAC === 'DISTINCT',
      'verdict=' + vAC + ' ratio=' + simAC.ratio.toFixed(3));

    // 5. determinism: recomputing A's signature twice gives byte-identical signatureSha256
    addRow('Recomputing the same document twice is byte-identical',
      a1.signatureSha256 === a2.signatureSha256 && a1.normalizedSha256 === a2.normalizedSha256,
      'sigHash match=' + (a1.signatureSha256 === a2.signatureSha256));

    // 6. edge case: too-short document reports INSUFFICIENT-DATA, does not throw
    const short = await impl.analyzeDoc("too few words", k, N);
    addRow('Under-length document reports INSUFFICIENT-DATA safely',
      short.shingleCount === 0,
      'shingleCount=' + short.shingleCount);

  } catch (err){
    addRow('Self-test threw an unexpected error', false, String(err && err.message || err));
  }

  return { pass: allPass, rows };
}

